use super::*;
use horizon_items::items::ItemInfo;
use serde_json::{Value, json};

// These exports were generated by the original HuskSync serializers against
// patched Paper 26.2. The inner field strings are reused without edits.
const EFFECTS_FIXTURE: &str = include_str!(
    "../../../horizon-items/tests/fixtures/husksync/husk-effects-attributes-26.2.json"
);
const RECORDS_FIXTURE: &str =
    include_str!("../../../horizon-items/tests/fixtures/husksync/husk-records-26.2.json");
const LIMITS: PackedLimits = PackedLimits {
    max_payload_bytes: 4096,
    max_json_bytes: 4096,
};

fn paper() -> Value {
    let mut snapshot: Value = serde_json::from_str(EFFECTS_FIXTURE).unwrap();
    let records: Value = serde_json::from_str(RECORDS_FIXTURE).unwrap();
    snapshot["data"]
        .as_object_mut()
        .unwrap()
        .extend(records["data"].as_object().unwrap().clone());
    snapshot
}

fn destination() -> Compound {
    let Tag::Compound(root) = nbt::parse_snbt(r#"{
        DataVersion:5023,UUID:[I;11,22,33,44],Pos:[12.0d,64.0d,-19.0d],Dimension:"minecraft:the_nether",
        Rotation:[20.0f,40.0f],Motion:[0.1d,0.0d,0.2d],OnGround:1b,playerGameType:1,previousPlayerGameType:0,
        abilities:{flying:1b,mayfly:1b,walkSpeed:0.15f},respawn:{dimension:"minecraft:overworld",pos:[I;2,64,3],forced:1b},
        AbsorptionAmount:3.0f,foodTickTimer:31,Score:511,XpSeed:23,Air:299s,
        SelectedItemSlot:0,Inventory:[{Slot:0b,id:"minecraft:stone",count:4}],
        equipment:{chest:{id:"minecraft:iron_chestplate",count:1},saddle:{id:"minecraft:saddle",count:1}},
        attributes:[{id:"minecraft:luck",base:4.0d,modifiers:[{id:"oracle:stale",amount:2.0d,operation:"add_value"}],unknown:7b},{id:"pigeon:unrelated",base:99.0d,unknown:1b}],
        active_effects:[{id:"minecraft:strength",duration:200,show_icon:1b}],
        recipeBook:{recipes:["minecraft:keep","minecraft:old"],toBeDisplayed:["minecraft:keep","minecraft:old"],isGuiOpen:1b,"pigeon:custom_book":{"marker":17}},
        BukkitValues:{"fixture:stale":9b},NeoForgeData:{PlayerPersisted:{"slimefun:local":"未覆盖"}},
        "pigeon:local_only":{"some":42}
    }"#).unwrap().0 else { panic!("destination fixture") };
    root
}

fn items() -> Items {
    let mut items = Items::empty();
    for id in [
        "minecraft:diamond",
        "minecraft:torch",
        "minecraft:iron_boots",
        "minecraft:iron_helmet",
        "minecraft:shield",
        "minecraft:gold_ingot",
    ] {
        items.items.insert(
            id.into(),
            ItemInfo {
                id: id.into(),
                max_stack: 64,
                ..ItemInfo::default()
            },
        );
    }
    items
}

fn catalog() -> Catalog {
    let bits = |value: f64| format!("{:016x}", value.to_bits());
    Catalog::from_json(&json!({
        "data_version": DATA_VERSION,
        "attributes":[
            {"id":"minecraft:max_health","default":bits(20.0),"min":bits(1.0),"max":bits(1024.0),"syncable":true},
            {"id":"minecraft:movement_speed","default":bits(0.1),"min":bits(0.0),"max":bits(1024.0),"syncable":true},
            {"id":"minecraft:attack_damage","default":bits(1.0),"min":bits(0.0),"max":bits(2048.0),"syncable":true},
            {"id":"minecraft:luck","default":bits(0.0),"min":bits(-1024.0),"max":bits(1024.0),"syncable":true}
        ],
        "entities":{"minecraft:player":{
            "minecraft:max_health":bits(20.0),"minecraft:movement_speed":bits(0.1),
            "minecraft:attack_damage":bits(1.0),"minecraft:luck":bits(0.0)
        }}
    })).unwrap()
}

fn recipes() -> RecipeIndex {
    RecipeIndex::load_from_sources(&[
        ("old".into(), json!({"type":"minecraft:crafting_shapeless"})),
        (
            "keep".into(),
            json!({"type":"minecraft:crafting_shapeless"}),
        ),
        ("new".into(), json!({"type":"minecraft:crafting_shapeless"})),
        (
            "special".into(),
            json!({"type":"minecraft:crafting_special_mapcloning"}),
        ),
    ])
}

fn envelope_bytes(packed: &Value) -> Vec<u8> {
    let husk = serde_json::to_vec(packed).unwrap();
    SnapshotEnvelope {
        health: 87.25,
        recipes: [
            "minecraft:keep".into(),
            "minecraft:new".into(),
            "minecraft:missing".into(),
            "minecraft:special".into(),
        ]
        .into(),
        sections: [(
            "slimefun".into(),
            b"SFP1 synthetic participant bytes".as_slice(),
        )]
        .into(),
        husk: &husk,
    }
    .encode(4096)
    .unwrap()
}

fn projection<'a>(
    encoded: &'a [u8],
    destination: &Compound,
) -> Result<StagedPaperMigration<'a>, PaperMigrationError> {
    let envelope = SnapshotEnvelope::decode(encoded, 4096).unwrap();
    stage_paper_migration(
        &envelope,
        destination,
        &PaperMigrationContext {
            items: &items(),
            attributes: &catalog(),
            recipes: &recipes(),
            compression: PackedCompression::Json,
            limits: LIMITS,
        },
    )
}

#[test]
fn projects_real_paper_fields_and_the_native_loader_restores_them_without_local_changes() {
    let encoded = envelope_bytes(&paper());
    let destination = destination();
    let staged = projection(&encoded, &destination).unwrap();
    assert_eq!(
        staged.sections["slimefun"],
        b"SFP1 synthetic participant bytes"
    );
    assert_eq!(
        staged.health.initial.to_bits(),
        (73.12345678912345f64 as f32).to_bits()
    );
    assert_eq!(staged.health.after_bridges, 87.25);
    assert_eq!(
        staged.health.husk.health_scale.to_bits(),
        (-0.0f64).to_bits()
    );
    assert!(staged.health.husk.is_health_scaled);
    assert_eq!(staged.statistics.generic["jump"], 32);
    assert_eq!(staged.statistics.blocks["mined"]["stone"], 21);
    assert_eq!(staged.statistics.items["used"]["stone_pickaxe"], 8);
    assert_eq!(staged.statistics.entities["killed"]["zombie"], 6);
    assert_eq!(
        staged.advancements[&Identifier::parse("minecraft:story/mine_stone").unwrap()]["get_stone"],
        1700010000123
    );
    assert_eq!(
        staged.advancements[&Identifier::parse("pigeon:record_fixture").unwrap()]["second"],
        -1234
    );
    for key in [
        "DataVersion",
        "UUID",
        "Pos",
        "Rotation",
        "Dimension",
        "Motion",
        "OnGround",
        "respawn",
        "playerGameType",
        "previousPlayerGameType",
        "abilities",
        "AbsorptionAmount",
        "foodTickTimer",
        "Score",
        "XpSeed",
        "Air",
        "NeoForgeData",
        "pigeon:local_only",
    ] {
        assert_eq!(
            staged.player[&key.into()],
            destination[&key.into()],
            "local state {key}"
        );
    }
    let player = Tag::Compound(staged.player);
    let equipment = player.get("equipment").unwrap();
    assert!(equipment.get("chest").is_none());
    assert_eq!(
        equipment.get("saddle"),
        destination[&"equipment".into()].get("saddle")
    );
    let Some(Tag::List(slots)) = player.get("Inventory") else {
        panic!("projected inventory")
    };
    let diamond = &slots[0];
    let components = diamond.get("components").unwrap();
    assert_eq!(
        components.get("minecraft:custom_name"),
        Some(&string("原有名称"))
    );
    assert_eq!(
        components.get("minecraft:lore"),
        Some(&Tag::List(vec![string("原有描述"), string("旧物品 🙂")]))
    );
    assert_eq!(
        player.get("BukkitValues").unwrap().get("fixture:long"),
        Some(&Tag::Long(987654321123))
    );
    assert!(
        player
            .get("BukkitValues")
            .unwrap()
            .get("fixture:stale")
            .is_none()
    );
    let Some(Tag::List(attributes)) = player.get("attributes") else {
        panic!("projected attributes")
    };
    let luck = attributes
        .iter()
        .find(|entry| entry.get("id") == Some(&string("minecraft:luck")))
        .unwrap();
    assert_eq!(luck.get("base"), Some(&Tag::Double(4.0f64.to_bits())));
    assert!(luck.get("modifiers").is_none());
    assert_eq!(luck.get("unknown"), Some(&Tag::Byte(7)));
    let unrelated = attributes
        .iter()
        .find(|entry| entry.get("id") == Some(&string("pigeon:unrelated")))
        .unwrap();
    assert_eq!(unrelated.get("unknown"), Some(&Tag::Byte(1)));
    let mut live =
        crate::living_attributes::new_live(&std::sync::Arc::new(catalog()), PLAYER).unwrap();
    crate::living_attributes::apply_saved(&mut live, player.get("attributes")).unwrap();
    use horizon_world::attribute_map::ValueKind;
    assert_eq!(
        live.value(live.key("minecraft:max_health"), ValueKind::Computed)
            .unwrap(),
        1024.0
    );
    assert_eq!(
        live.value(live.key("minecraft:attack_damage"), ValueKind::Computed)
            .unwrap(),
        8.015625
    );
    let raw_recipe = player.get("recipeBook").unwrap();
    assert_eq!(raw_recipe.get("isGuiOpen"), Some(&Tag::Byte(1)));
    assert_eq!(
        raw_recipe.get("pigeon:custom_book"),
        destination[&"recipeBook".into()].get("pigeon:custom_book")
    );
    let level = super::super::playerdata::saved_player(player);
    assert_eq!(level.selected_slot, 4);
    assert_eq!(level.food, 27);
    assert_eq!(level.saturation.to_bits(), (-0.0f32).to_bits());
    assert_eq!(level.food_exhaustion, -3.25);
    assert_eq!((level.xp_level, level.xp_total), (37, 123456789));
    assert_eq!((level.score, level.xp_seed), (511, 23));
    assert_eq!(level.inventory.iter().filter(|item| item.0 == 4).count(), 1);
    assert!(
        level
            .inventory
            .iter()
            .any(|item| item.0 == 100 && item.1 == "minecraft:iron_boots")
    );
    assert!(
        level
            .inventory
            .iter()
            .any(|item| item.0 == 150 && item.1 == "minecraft:shield")
    );
    assert_eq!(level.ender_items[26].as_ref().unwrap().count, 11);
    assert_eq!(level.active_effects.len(), 2);
    assert_eq!(
        (
            level.active_effects[0].id.as_str(),
            level.active_effects[0].amplifier,
            level.active_effects[0].duration
        ),
        ("minecraft:speed", 255, -1)
    );
    assert_eq!(
        level.recipe_book.recipes,
        ["minecraft:keep".into(), "minecraft:new".into()].into()
    );
    assert_eq!(level.recipe_book.to_be_displayed, level.recipe_book.recipes);
}

#[test]
fn rejects_late_source_errors_and_leaves_the_destination_untouched() {
    let destination = destination();
    let trusted = destination.clone();
    let mut incoming = paper();
    let effects = incoming["data"]["husksync:potion_effects"]
        .as_str()
        .unwrap();
    incoming["data"]["husksync:potion_effects"] = effects
        .replace("minecraft:speed", "pigeon:missing_effect")
        .into();
    assert!(
        matches!(projection(&envelope_bytes(&incoming), &destination), Err(PaperMigrationError::Effect(id)) if id == "pigeon:missing_effect")
    );
    assert_eq!(destination, trusted);

    let mut incoming = paper();
    let attrs = incoming["data"]["husksync:attributes"].as_str().unwrap();
    incoming["data"]["husksync:attributes"] = attrs.replace("5.25", "-300.0").into();
    assert!(
        matches!(projection(&envelope_bytes(&incoming), &destination), Err(PaperMigrationError::AttributeBounds(id)) if id == "minecraft:max_health")
    );
    assert_eq!(destination, trusted);

    let mut wrong = destination.clone();
    wrong.insert("DataVersion".into(), Tag::Int(4903));
    assert!(matches!(
        projection(&envelope_bytes(&paper()), &wrong),
        Err(PaperMigrationError::Destination("DataVersion"))
    ));
    let mut incoming = paper();
    incoming["data"]["husksync:flight_status"] = "{}".into();
    assert!(
        matches!(projection(&envelope_bytes(&incoming), &destination), Err(PaperMigrationError::Snapshot(message)) if message.contains("must keep husksync:flight_status local"))
    );
    assert_eq!(destination, trusted);
}
